  ('ramayana-manas-kevat-crossing-v1', 'rama-blesses-kevat-and-the-road-continues', 8, '{"snapshotContract":"DEVAM_RAMAYANA_EXPECTED_STORIES_BEGINNINGS_EXILE_DB_V1","storyId":"ramayana-manas-kevat-crossing-v1","sourceId":"ramcharitmanas-belvedere-fixed-scan","scanSha256":"6d570d531ebada1912f6e930212393fec2200765a0b731b73b8e7135ea0f70f2","scanPages":[531]}'::jsonb)
) as source(moment_slug, beat_slug, beat_ordinal, source_range)
join public.narrative_series series on series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1'
join public.narrative_moments moment on moment.series_id=series.id and moment.slug=source.moment_slug
on conflict (moment_id, slug) do update set beat_ordinal=excluded.beat_ordinal, source_range=excluded.source_range,
  visual_direction=excluded.visual_direction, rights_lane=excluded.rights_lane, publication_state=excluded.publication_state, updated_at=now();

insert into public.narrative_beat_texts (beat_id, language_code, title, narration, text_status, rights_lane, publication_state)
select beat.id, source.language_code, source.title, source.narration, 'source_aligned', 'derivative_allowed', 'draft'
from (values
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-and-sati-hear-rama-katha', 'en', 'Shiva and Sati listen at Agastya''s hermitage', 'Shiva visits the sage Agastya with Sati, and the sage receives them with reverence before narrating Rama''s story. Shiva listens with delight and later speaks about devotion; the frame establishes that Rama''s life is being heard, remembered and retold before the main birth narrative begins.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-and-sati-hear-rama-katha', 'hi', 'शिव और सती अगस्त्य आश्रम में रामकथा सुनते हैं', 'शिव सती के साथ अगस्त्य मुनि के आश्रम पहुँचते हैं। मुनि उनका आदर करते हैं और रामकथा सुनाते हैं। शिव आनंद से कथा सुनते हैं और आगे भक्ति की चर्चा करते हैं; इस प्रकार मुख्य जन्मकथा से पहले ही राम का जीवन सुनने, स्मरण करने और दोबारा कहने की परंपरा स्थापित हो जाती है।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-sees-rama-searching', 'en', 'Sati sees Rama grieving in the forest', 'On the journey onward, Shiva sees Rama and Lakshmana searching through the forest after Sita''s abduction and bows to Rama. Sati cannot reconcile Shiva''s reverence with the sight of a prince overwhelmed by separation. Her uncertainty is not a side note: it becomes the question that drives the entire frame.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-sees-rama-searching', 'hi', 'सती वन में व्याकुल राम को देखती हैं', 'आगे जाते समय शिव वन में सीता की खोज करते राम और लक्ष्मण को देखते हैं और राम को प्रणाम करते हैं। विरह से व्याकुल एक राजकुमार के सामने शिव का झुकना सती की समझ में नहीं आता। उनका यही संशय इस पूरी कथा-भूमिका को आगे बढ़ाता है।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-takes-sitas-form', 'en', 'Sati decides to test what Shiva has told her', 'Shiva explains that Rama is the reality praised by the sacred tradition and leaves Sati free to examine her doubt. Sati approaches Rama in Sita''s appearance. Rama immediately recognizes her, greets her in relation to Shiva and asks why she is alone, so the disguise does not produce the test she expected.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-takes-sitas-form', 'hi', 'सती शिव की बात परखने का निर्णय लेती हैं', 'शिव समझाते हैं कि राम वही परम सत्ता हैं जिनकी महिमा परंपरा में कही गई है, फिर सती को अपना संशय परखने देते हैं। सती सीता का रूप बनाकर राम के सामने जाती हैं। राम उन्हें तुरंत पहचान लेते हैं, शिव से उनका संबंध मानकर अभिवादन करते हैं और उनके अकेले आने का कारण पूछते हैं; इस तरह सती की बनाई परीक्षा उलट जाती है।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-confronts-the-vision', 'en', 'The vision leaves Sati unable to maintain her certainty', 'As Sati turns away, the telling surrounds her with repeated visions of Rama, Sita and Lakshmana and with divine forms that exceed the ordinary scene she thought she was testing. She returns shaken. When Shiva asks what happened, she says she merely bowed as he had; Shiva understands both the test and the concealment without forcing a confession.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-confronts-the-vision', 'hi', 'दिव्य दर्शन सती के पुराने विश्वास को तोड़ देता है', 'लौटते समय सती को राम, सीता और लक्ष्मण के अनेक रूप तथा ऐसे दिव्य दर्शन दिखाई देते हैं जो उनकी साधारण परीक्षा की सीमा से बाहर हैं। वे विचलित होकर शिव के पास लौटती हैं। पूछने पर कहती हैं कि उन्होंने केवल प्रणाम किया था; शिव बिना उनसे स्वीकारोक्ति कराए परीक्षा और उसे छिपाने की बात समझ लेते हैं।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-withdraws-from-marital-bond', 'en', 'A private decision changes Shiva and Sati''s life', 'Because Sati assumed the appearance of Sita, whom Shiva honours as Rama''s consort, Shiva resolves inwardly not to continue the marital bond in the same way. He does not publicly humiliate Sati, but the distance is real and Sati understands its cause. The story treats this rupture as a grave consequence of the failed test and concealed truth.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-withdraws-from-marital-bond', 'hi', 'शिव का मौन निर्णय उनके संबंध को बदल देता है', 'सती ने सीता का रूप धारण किया था, जिन्हें शिव राम की अर्धांगिनी मानकर पूजते हैं। इसलिए शिव मन में दांपत्य संबंध को पहले की तरह न निभाने का संकल्प करते हैं। वे सती का सार्वजनिक अपमान नहीं करते, पर दूरी वास्तविक है और सती उसका कारण समझ जाती हैं। कथा इस टूटन को परीक्षा और बात छिपाने का गंभीर परिणाम बनाती है।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-goes-to-dakshas-sacrifice', 'en', 'Daksha''s sacrifice becomes the next point of rupture', 'Sati learns that her father Daksha is holding a great sacrifice and wishes to visit her family even though Shiva has not been invited. Shiva warns that arriving uninvited where hostility already exists may bring pain, but Sati chooses to go. At the sacrifice she finds little welcome and sees that Shiva''s share and honour have deliberately been withheld.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-goes-to-dakshas-sacrifice', 'hi', 'दक्ष का यज्ञ अगली निर्णायक टूटन बनता है', 'सती को पता चलता है कि उनके पिता दक्ष बड़ा यज्ञ कर रहे हैं और वे मायके जाना चाहती हैं, जबकि शिव को बुलाया नहीं गया। शिव समझाते हैं कि जहाँ पहले से वैर हो वहाँ बिना बुलाए जाना दुख दे सकता है, फिर भी सती जाने का निर्णय लेती हैं। यज्ञ में उन्हें सच्चा स्वागत नहीं मिलता और वे देखती हैं कि शिव का भाग और सम्मान जानबूझकर रोका गया है।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-renounces-her-body', 'en', 'Sati rejects the body tied to Daksha''s insult', 'Unable to accept the insult directed at Shiva and the identity she received through Daksha, Sati addresses the assembly and gives up her body through yogic fire. The sacrifice collapses into violence and grief as Shiva''s attendants retaliate. This is a sacred-narrative death, not a practice for imitation or a justification of self-harm.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-renounces-her-body', 'hi', 'सती दक्ष के अपमान से जुड़ी देह का त्याग करती हैं', 'शिव के अपमान और दक्ष से मिली अपनी देह के संबंध को स्वीकार न कर सकने पर सती सभा को संबोधित करती हैं और योगाग्नि से देह त्याग देती हैं। शिवगण प्रतिशोध लेते हैं और यज्ञ हिंसा तथा शोक में टूट जाता है। यह पवित्र कथा का प्रसंग है, अनुकरण योग्य आचरण या आत्महानि का समर्थन नहीं।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-is-reborn-as-parvati', 'en', 'The relationship begins again through Parvati', 'Sati is reborn as Parvati, daughter of Himavan and Mena. Narada reads the signs of her future and indicates that Shiva is her destined husband, although his ascetic appearance troubles her parents. Parvati accepts the direction of the prophecy and turns toward the demanding work of winning Shiva through devotion and tapas.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'sati-is-reborn-as-parvati', 'hi', 'पार्वती के जन्म से संबंध की नई यात्रा शुरू होती है', 'सती हिमवान और मैना की पुत्री पार्वती के रूप में जन्म लेती हैं। नारद उनके भविष्य के संकेत बताते हैं और कहते हैं कि शिव उनके पति होंगे, यद्यपि शिव का तपस्वी रूप माता-पिता को चिंतित करता है। पार्वती इस दिशा को स्वीकार करती हैं और भक्ति तथा तप के कठिन मार्ग पर चल पड़ती हैं।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'parvati-persists-in-tapas', 'en', 'Parvati''s resolve survives hardship and persuasion', 'Parvati leaves ordinary comfort and intensifies her austerity over a long period, eventually giving up even leaves. Sages test her commitment by criticizing Shiva as an unsuitable husband. She refuses to exchange her chosen path for a more conventional match, making her own sustained resolve—not parental arrangement—the centre of this part of the story.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'parvati-persists-in-tapas', 'hi', 'पार्वती का संकल्प कठिनाई और समझाइश दोनों से नहीं टूटता', 'पार्वती सामान्य सुख छोड़कर लंबे समय तक तप को कठोर बनाती जाती हैं और अंततः पत्ते तक त्याग देती हैं। ऋषि शिव को अनुपयुक्त वर बताकर उनके निश्चय की परीक्षा लेते हैं। पार्वती किसी अधिक सुविधाजनक संबंध के लिए अपना चुना मार्ग नहीं छोड़तीं; इस प्रसंग का केंद्र उनका दीर्घ और स्वयं चुना हुआ संकल्प है।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'kama-awakens-shiva', 'en', 'The gods'' urgency leads to Kama''s destruction', 'The gods need a child of Shiva who can defeat Taraka, so Kama is sent to disturb Shiva''s meditation. Desire spreads through the world, but when Kama releases his influence toward Shiva, Shiva opens his third eye and burns him. Rati grieves; Shiva grants that Kama will continue without a visible body and will later regain embodied union in another divine story.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'kama-awakens-shiva', 'hi', 'देवताओं की उतावली कामदेव के दहन तक पहुँचती है', 'देवताओं को तारक का अंत करने वाले शिवपुत्र की आवश्यकता है, इसलिए कामदेव को शिव की समाधि भंग करने भेजा जाता है। संसार में काम का प्रभाव फैलता है, पर शिव की ओर बाण चलने पर तीसरा नेत्र खुलता है और कामदेव भस्म हो जाते हैं। रति के शोक पर शिव वर देते हैं कि कामदेव अनंग रूप में रहेंगे और आगे एक अन्य दिव्य कथा में फिर मिलन पाएँगे।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-accepts-parvati', 'en', 'Shiva accepts the marriage after Parvati''s steadfastness', 'The gods present their need, while Parvati''s tapas has already established her commitment. Shiva agrees to the marriage and the sages carry the proposal to Himavan''s household. The movement toward marriage therefore joins several strands—Parvati''s choice, Shiva''s consent and the divine world''s need—without reducing the union to only one of them.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-accepts-parvati', 'hi', 'पार्वती की अडिगता के बाद शिव विवाह स्वीकार करते हैं', 'देवता अपनी आवश्यकता रखते हैं, जबकि पार्वती का तप पहले ही उनके संकल्प को सिद्ध कर चुका है। शिव विवाह स्वीकार करते हैं और ऋषि हिमवान के घर प्रस्ताव लेकर जाते हैं। इस प्रकार विवाह की दिशा में पार्वती की इच्छा, शिव की सहमति और देवताओं की आवश्यकता—तीनों जुड़ते हैं; कथा किसी एक कारण तक सीमित नहीं रहती।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'the-ascetic-wedding-procession', 'en', 'Shiva''s procession overturns ordinary wedding expectations', 'Shiva arrives surrounded by an extraordinary ascetic and supernatural company whose appearance frightens onlookers and especially Mena. The divine party helps the household perceive Shiva beyond that first shock. Once fear and misunderstanding are addressed, the families and sacred witnesses proceed with the wedding.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'the-ascetic-wedding-procession', 'hi', 'शिव की बारात सामान्य विवाह-कल्पना को उलट देती है', 'शिव ऐसी अद्भुत तपस्वी और अलौकिक मंडली के साथ आते हैं जिसे देखकर नगरवासी और विशेषकर मैना भयभीत हो जाती हैं। देवसमूह परिवार को पहली चौंकाने वाली छवि से आगे शिव का स्वरूप समझने में सहायता करता है। भय और भ्रम शांत होने के बाद परिवार तथा साक्षी विवाह की विधि आगे बढ़ाते हैं।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-and-parvati-return-to-kailasa', 'en', 'Parvati leaves her parents and begins life at Kailasa', 'The wedding is completed, Parvati''s family experiences the joy and pain of farewell, and Shiva returns with her to Kailasa. The telling briefly follows their settled union and the birth of Kartikeya, who defeats Taraka. That consequence closes the danger that had made the gods press for Shiva''s marriage.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'shiva-and-parvati-return-to-kailasa', 'hi', 'पार्वती विदा होकर कैलास में नया जीवन आरंभ करती हैं', 'विवाह पूरा होता है, पार्वती का परिवार विदाई के आनंद और दुख दोनों से गुजरता है, और शिव उन्हें लेकर कैलास लौटते हैं। कथा उनके स्थापित दांपत्य और कार्तिकेय के जन्म का संकेत देती है; कार्तिकेय तारक का वध करते हैं। इससे वह संकट समाप्त होता है जिसके कारण देवता विवाह के लिए व्याकुल थे।'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'parvati-asks-without-satis-old-doubt', 'en', 'Parvati asks Shiva to unfold Rama''s story', 'At Kailasa, Parvati approaches the question that once defeated Sati, but now asks with trust and a desire to understand. She asks about Rama''s divine identity, birth, childhood, marriage, exile and later deeds. Shiva recognizes that the old doubt has passed and begins the extended narration that carries the Ramcharitmanas forward.'),
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'parvati-asks-without-satis-old-doubt', 'hi', 'पार्वती शिव से रामकथा विस्तार से कहने का अनुरोध करती हैं', 'कैलास में पार्वती उसी प्रश्न के पास लौटती हैं जिसमें सती उलझी थीं, पर अब उनका भाव विश्वास और समझने की इच्छा का है। वे राम के दिव्य स्वरूप, जन्म, बालचरित, विवाह, वनवास और आगे की कथा पूछती हैं। शिव समझते हैं कि पुराना संशय मिट चुका है और वही विस्तृत रामकथा आरंभ करते हैं जो रामचरितमानस को आगे ले जाती है।'),
  ('ramayana-manas-narada-delusion-v1', 'narada-remains-unmoved-by-kama', 'en', 'Kama cannot break Narada''s meditation', 'Narada enters deep meditation. Indra fears that such austerity may threaten his position and sends Kama with the powers of spring and attraction, but Narada remains undisturbed. The victory is protected by divine grace; the danger begins when Narada starts treating it as proof of his own superiority.'),
  ('ramayana-manas-narada-delusion-v1', 'narada-remains-unmoved-by-kama', 'hi', 'कामदेव नारद की समाधि नहीं तोड़ पाते', 'नारद गहरी समाधि में जाते हैं। इंद्र को भय होता है कि यह तप उनके पद के लिए चुनौती बन सकता है, इसलिए वे कामदेव को वसंत और आकर्षण की शक्तियों के साथ भेजते हैं। नारद विचलित नहीं होते, पर संकट तब शुरू होता है जब वे इस कृपा-समर्थित विजय को अपनी व्यक्तिगत श्रेष्ठता मानने लगते हैं।'),
  ('ramayana-manas-narada-delusion-v1', 'shiva-warns-narada-about-pride', 'en', 'Shiva recognizes what the victory is doing to Narada', 'Narada tells Shiva that Kama could not move him. Shiva congratulates him but warns him not to parade the victory before Vishnu, even if the subject arises. Narada dislikes the warning because he still sees the episode as an achievement to be admired rather than a moment requiring humility.'),
  ('ramayana-manas-narada-delusion-v1', 'shiva-warns-narada-about-pride', 'hi', 'शिव नारद की विजय में उभरता अभिमान पहचान लेते हैं', 'नारद शिव को बताते हैं कि कामदेव उन्हें विचलित नहीं कर सके। शिव उन्हें शुभकामना देते हुए सावधान करते हैं कि वे इस विजय का प्रदर्शन विष्णु के सामने न करें, प्रसंग आने पर भी नहीं। नारद को यह सलाह अच्छी नहीं लगती, क्योंकि वे अभी भी घटना को विनम्रता के अवसर के बजाय प्रशंसा योग्य उपलब्धि मान रहे हैं।'),
  ('ramayana-manas-narada-delusion-v1', 'narada-boasts-before-vishnu', 'en', 'Narada tells Vishnu the story Shiva asked him to withhold', 'Narada goes to Vishnu and recounts his triumph. Vishnu responds gently while perceiving the pride beneath the report. Rather than arguing with Narada, Vishnu allows a carefully bounded delusion to unfold, aimed in the telling at removing the pride that direct advice has not reached.'),
  ('ramayana-manas-narada-delusion-v1', 'narada-boasts-before-vishnu', 'hi', 'नारद वही बात विष्णु को कहते हैं जिसे शिव ने रोकने को कहा था', 'नारद विष्णु के पास जाकर अपनी विजय सुनाते हैं। विष्णु को कथा के भीतर छिपा अभिमान दिखाई देता है, फिर भी वे कोमलता से उत्तर देते हैं। सीधे विवाद करने के बजाय वे एक सीमित मोह-लीला घटने देते हैं, जिसका उद्देश्य उस अभिमान को हटाना है जहाँ सलाह नहीं पहुँच सकी।'),
  ('ramayana-manas-narada-delusion-v1', 'vishwamohini-and-the-enchanted-city', 'en', 'An enchanting city and princess redirect Narada''s desire', 'Narada encounters a splendid city ruled by Shilanidhi and sees the king''s daughter Vishwamohini, whose svayamvara is approaching. On reading the signs associated with her future husband, Narada withholds their full meaning from the king and begins wanting that future for himself. His spiritual pride has now become personal desire and calculation.'),
  ('ramayana-manas-narada-delusion-v1', 'vishwamohini-and-the-enchanted-city', 'hi', 'मोहक नगर और राजकुमारी नारद की इच्छा को नई दिशा देते हैं', 'नारद शीलनिधि के भव्य नगर में पहुँचते हैं और उनकी पुत्री विश्वमोहिनी को देखते हैं, जिसका स्वयंवर होने वाला है। उसके भावी पति से जुड़े लक्षण समझकर नारद राजा को पूरा अर्थ नहीं बताते और उस भविष्य को अपने लिए चाहने लगते हैं। आध्यात्मिक अभिमान अब निजी इच्छा और गणना में बदल जाता है।'),
  ('ramayana-manas-narada-delusion-v1', 'narada-asks-for-haris-form', 'en', 'Narada asks Vishnu to make him irresistible', 'Narada asks Vishnu for Hari''s own beauty so that the princess will choose him. Vishnu promises to do what serves Narada''s highest welfare, not simply what his immediate desire demands. Narada enters the assembly confident that he bears a divine appearance, unaware that the telling has given his face a monkey-like form.'),
  ('ramayana-manas-narada-delusion-v1', 'narada-asks-for-haris-form', 'hi', 'नारद विष्णु से आकर्षक रूप माँगते हैं', 'नारद विष्णु से हरि जैसा रूप माँगते हैं ताकि राजकुमारी उन्हें चुने। विष्णु तत्काल इच्छा पूरी करने के बजाय वही करने का आश्वासन देते हैं जो नारद के परम हित में हो। नारद इस विश्वास से सभा में बैठते हैं कि उनका रूप दिव्य है, जबकि कथा में उनका चेहरा वानर जैसा दिखाई दे रहा है।'),
  ('ramayana-manas-narada-delusion-v1', 'vishwamohini-chooses-vishnu', 'en', 'The svayamvara exposes the gap between confidence and reality', 'Shiva''s attendants, present in disguise, hint at Narada''s appearance, but he hears their words as praise. Vishwamohini does not choose him and instead places the garland on Vishnu, who has appeared as a king. Narada''s imagined certainty collapses in public, turning desire into humiliation and rage.'),
  ('ramayana-manas-narada-delusion-v1', 'vishwamohini-chooses-vishnu', 'hi', 'स्वयंवर आत्मविश्वास और वास्तविकता का अंतर खोल देता है', 'वेश बदलकर उपस्थित शिवगण नारद के रूप की ओर संकेत करते हैं, पर नारद उनकी बात को प्रशंसा समझते हैं। विश्वमोहिनी उन्हें नहीं चुनती और राजा के रूप में आए विष्णु को वरमाला पहनाती है। नारद का कल्पित विश्वास सभा में टूट जाता है और इच्छा अपमान तथा क्रोध में बदल जाती है।'),
  ('ramayana-manas-narada-delusion-v1', 'narada-sees-his-face-and-curses', 'en', 'Narada''s anger becomes a chain of curses', 'After seeing his reflection, Narada curses Shiva''s attendants to be born as formidable demons. Meeting Vishnu with the princess, he accuses him of deception and curses him to take human form, suffer separation from his wife and depend on monkeys for help. These words later function within this telling as one strand in the causes of the Rama incarnation.'),
  ('ramayana-manas-narada-delusion-v1', 'narada-sees-his-face-and-curses', 'hi', 'नारद का क्रोध श्रापों की श्रृंखला बन जाता है', 'अपना प्रतिबिंब देखकर नारद शिवगणों को भयंकर राक्षस रूप में जन्म लेने का श्राप देते हैं। राजकुमारी के साथ विष्णु को देखकर वे छल का आरोप लगाते हैं और श्राप देते हैं कि विष्णु मनुष्य बनें, पत्नी-वियोग सहें और वानरों की सहायता लें। इसी कथा में आगे ये शब्द रामावतार के कारणों की एक धारा बनते हैं।'),
  ('ramayana-manas-narada-delusion-v1', 'maya-lifts-and-narada-repents', 'en', 'When the delusion lifts, Narada sees his own part', 'Vishnu withdraws the enchanted scene, and Narada suddenly sees the pride, desire and anger that carried him through it. He asks that his curse be undone. Vishnu does not erase the spoken consequence, but calms him, restores his understanding and directs him toward devotion rather than self-condemnation.'),
  ('ramayana-manas-narada-delusion-v1', 'maya-lifts-and-narada-repents', 'hi', 'मोह हटने पर नारद अपनी भूमिका पहचानते हैं', 'विष्णु मोह-रचना हटा लेते हैं और नारद को अपना अभिमान, इच्छा तथा क्रोध साफ दिखाई देने लगता है। वे श्राप वापस लेने की विनती करते हैं। विष्णु बोले हुए परिणाम को मिटाते नहीं, पर उन्हें शांत करते हैं, समझ लौटाते हैं और आत्मदंड के बजाय भक्ति की दिशा देते हैं।'),
  ('ramayana-manas-narada-delusion-v1', 'narada-reconciles-with-shivas-attendants', 'en', 'The cursed attendants receive a limit and a path back', 'Shiva''s attendants approach Narada in fear and remorse. Narada explains that the curse will make them powerful demons, but that Vishnu''s incarnation will defeat them and release them. The resolution does not pretend the angry words were harmless; it places an eventual end around their consequence.'),
  ('ramayana-manas-narada-delusion-v1', 'narada-reconciles-with-shivas-attendants', 'hi', 'श्रापित शिवगणों को सीमा और वापसी का मार्ग मिलता है', 'शिवगण भय और पश्चाताप के साथ नारद के पास आते हैं। नारद बताते हैं कि श्राप से वे शक्तिशाली राक्षस बनेंगे, पर विष्णु का अवतार उनका अंत करके मुक्ति देगा। समाधान क्रोध में बोले शब्दों को निष्फल नहीं बताता; वह उनके परिणाम के चारों ओर एक अंतिम सीमा रखता है।'),
  ('ramayana-manas-narada-delusion-v1', 'curse-becomes-one-incarnation-cause', 'en', 'A failure of humility is woven into the incarnation story', 'Narada resumes his journey singing Rama''s qualities. The narrator links his curse to one cycle in which Vishnu takes human form, experiences separation and receives monkey allies. This is one Ramcharitmanas causal account among several placed side by side, not a demand that all versions share one origin chain.'),
  ('ramayana-manas-narada-delusion-v1', 'curse-becomes-one-incarnation-cause', 'hi', 'विनम्रता की विफलता अवतार-कथा में जुड़ जाती है', 'नारद राम के गुण गाते हुए आगे बढ़ते हैं। कथावाचक उनके श्राप को उस कल्प की एक कारण-रेखा से जोड़ता है जिसमें विष्णु मनुष्य बनते हैं, वियोग सहते हैं और वानर सहयोगी पाते हैं। रामचरितमानस स्वयं कई कारण साथ रखता है; इसे हर रामायण की एकमात्र उत्पत्ति-श्रृंखला नहीं माना जाता।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'manu-and-shatarupa-leave-the-kingdom', 'en', 'A fulfilled royal life still leaves an unanswered longing', 'Svayambhuva Manu and Shatarupa have governed, sustained a family and fulfilled their public responsibilities. With age, Manu feels that a life spent without directly realizing the divine remains incomplete. The couple hand responsibility onward and leave together; the quest belongs to both of them, not to Manu alone.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'manu-and-shatarupa-leave-the-kingdom', 'hi', 'सफल राजजीवन के बाद भी एक गहरी चाह शेष रहती है', 'स्वायंभुव मनु और शतरूपा राज्य चला चुके हैं, परिवार का पालन कर चुके हैं और सार्वजनिक उत्तरदायित्व निभा चुके हैं। आयु बढ़ने पर मनु को लगता है कि ईश्वर का प्रत्यक्ष अनुभव पाए बिना जीवन अधूरा है। दोनों उत्तरदायित्व आगे सौंपकर साथ निकलते हैं; यह खोज केवल मनु की नहीं, दोनों की है।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'the-couple-seek-through-pilgrimage-and-listening', 'en', 'They begin with pilgrimage, listening and remembrance', 'Manu and Shatarupa visit sacred places, live simply among sages and listen repeatedly to sacred narratives. They repeat the twelve-syllable mantra associated with Vishnu and gradually withdraw attention from royal identity. Their practice is shown as sustained orientation, not a single dramatic request for a boon.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'the-couple-seek-through-pilgrimage-and-listening', 'hi', 'वे तीर्थ, सत्संग और स्मरण से साधना आरंभ करते हैं', 'मनु और शतरूपा तीर्थों में जाते हैं, ऋषियों के बीच सरल जीवन बिताते हैं और बार-बार पवित्र कथाएँ सुनते हैं। वे विष्णु से जुड़े द्वादशाक्षर मंत्र का जप करते हुए राजसी पहचान से ध्यान हटाते हैं। उनकी साधना एक अचानक वर माँगने की घटना नहीं, लंबे समय की दिशा है।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'tapas-intensifies-over-time', 'en', 'Their austerity becomes progressively harder', 'Over a vast sacred timescale, the couple move from roots and fruit to water, then to air, and eventually stand in severe concentration. The bodies weaken but the desire for direct vision does not. The text''s extraordinary durations belong to devotional time and are not a health regimen for modern readers.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'tapas-intensifies-over-time', 'hi', 'उनका तप क्रमशः कठिन होता जाता है', 'पवित्र कथा के विशाल कालमान में दोनों पहले कंद-मूल और फल, फिर जल, फिर वायु पर रहते हुए अंततः अत्यंत कठिन एकाग्र तप करते हैं। शरीर क्षीण होता है, पर प्रत्यक्ष दर्शन की इच्छा नहीं घटती। ये असाधारण अवधियाँ भक्तिकथा के काल का हिस्सा हैं, आधुनिक स्वास्थ्य-विधि नहीं।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'lesser-boons-do-not-distract-them', 'en', 'They refuse to exchange the goal for an easier reward', 'Brahma, Vishnu and Shiva appear in the telling and invite the couple to ask for boons, yet their central longing remains unchanged: they want to behold the reality praised by the sacred tradition. A disembodied assurance finally tells them to ask, and strength returns so that they can receive the promised vision.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'lesser-boons-do-not-distract-them', 'hi', 'वे अपने लक्ष्य को किसी आसान वर से नहीं बदलते', 'कथा में ब्रह्मा, विष्णु और शिव उन्हें वर माँगने को कहते हैं, फिर भी उनकी मुख्य चाह नहीं बदलती—वे उस परम रूप का दर्शन चाहते हैं जिसकी महिमा परंपरा कहती है। अंततः आकाशवाणी उन्हें माँगने को कहती है और प्रतिज्ञात दर्शन ग्रहण करने के लिए उनके शरीर में शक्ति लौटती है।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'the-divine-couple-appears', 'en', 'The vision they sought stands before them', 'The divine appears before Manu and Shatarupa together with the primordial power who will be connected with Sita in the promised incarnation. The couple are overwhelmed and fall at the divine feet before being raised. The meeting turns years of impersonal longing into a relationship with a form they can love as parents.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'the-divine-couple-appears', 'hi', 'जिस दर्शन की चाह थी वह उनके सामने प्रकट होता है', 'मनु और शतरूपा के सामने परमात्मा उस आदिशक्ति के साथ प्रकट होते हैं जो आगे प्रतिज्ञात अवतार में सीता से जुड़ती हैं। दोनों भाव-विभोर होकर चरणों में गिरते हैं और उन्हें उठाया जाता है। लंबे समय की निराकार चाह अब ऐसे संबंध में बदलती है जिसे वे माता-पिता की तरह प्रेम कर सकें।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'manu-asks-for-a-son-like-god', 'en', 'Manu asks for a child equal to the one before him', 'Invited to choose a boon, Manu asks for a son like the divine presence before him. The request carries embarrassment because no created being can be an equal. The answer resolves the problem within the story: since no equal can be found, the divine will personally be born as Manu''s son.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'manu-asks-for-a-son-like-god', 'hi', 'मनु सामने खड़े प्रभु के समान पुत्र माँगते हैं', 'वर माँगने पर मनु सामने खड़े प्रभु के समान पुत्र चाहते हैं। उन्हें संकोच भी है, क्योंकि सृष्टि में उनका समकक्ष कोई नहीं। कथा का उत्तर इसी असंभवता को समाधान बनाता है—जब समान कोई नहीं मिल सकता, तब प्रभु स्वयं मनु के पुत्र बनेंगे।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'shatarupa-asks-for-devotion-and-understanding', 'en', 'Shatarupa makes the shared wish deeper and more precise', 'Shatarupa affirms Manu''s request but does not simply disappear behind it. She asks for the happiness, devotion, insight, way of life and love of the divine feet granted to true devotees. Her request ensures that receiving the divine as a child will remain a relationship of understanding and devotion, not possession.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'shatarupa-asks-for-devotion-and-understanding', 'hi', 'शतरूपा साझा इच्छा को और गहरा तथा स्पष्ट करती हैं', 'शतरूपा मनु के वर को स्वीकार करती हैं, पर उनकी अपनी वाणी भी निर्णायक है। वे सच्चे भक्तों को मिलने वाला सुख, भक्ति, विवेक, जीवन-पद्धति और प्रभुचरणों का प्रेम माँगती हैं। इससे दिव्य बालक को पाना अधिकार का विषय नहीं, समझ और भक्ति का संबंध बनता है।'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'the-promise-points-to-ayodhya', 'en', 'The boon is deferred into another birth', 'Manu asks that his attachment to the divine child be as indispensable as water to a fish. The divine grants the requests and tells the couple that after another phase of existence they will be born as rulers of Ayodhya; the divine and primordial power will then enter their household. The couple complete their present lives with the promise held inwardly.'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'the-promise-points-to-ayodhya', 'hi', 'वरदान एक अगले जन्म की ओर बढ़ता है', 'मनु चाहते हैं कि दिव्य पुत्र के प्रति उनका प्रेम मछली के लिए जल जितना अनिवार्य हो। वर स्वीकार होता है और दोनों को बताया जाता है कि एक अन्य जीवन-चरण के बाद वे अयोध्या के राजा-रानी बनेंगे; तब प्रभु और आदिशक्ति उनके घर जन्म लेंगे। दंपती इस प्रतिज्ञा को हृदय में रखकर अपना वर्तमान जीवन पूरा करते हैं।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'satyaketu-hands-rule-to-pratapbhanu', 'en', 'Pratapbhanu inherits a strong kingdom and enlarges it', 'King Satyaketu has two capable sons, Pratapbhanu and Arimardana. He gives the kingdom to the elder and withdraws to the forest. With his brother''s strength and the counsel of the wise minister Dharmaruchi, Pratapbhanu conquers rival rulers and establishes a prosperous order that the story initially praises.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'satyaketu-hands-rule-to-pratapbhanu', 'hi', 'प्रतापभानु को सुदृढ़ राज्य मिलता है और वे उसे फैलाते हैं', 'राजा सत्यकेतु के दो समर्थ पुत्र हैं—प्रतापभानु और अरिमर्दन। वे बड़े पुत्र को राज्य देकर वन चले जाते हैं। भाई की शक्ति और बुद्धिमान मंत्री धर्मरुचि की सलाह से प्रतापभानु प्रतिद्वंद्वी राजाओं को जीतते हैं और ऐसी समृद्ध व्यवस्था बनाते हैं जिसकी कथा आरंभ में प्रशंसा करती है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-hunt-separates-the-king', 'en', 'A boar draws the king away from every safeguard', 'During a hunt, an extraordinary boar draws Pratapbhanu deep into difficult forest and repeatedly escapes his arrows. The king becomes separated from his forces, exhausted and thirsty. The animal is Kalaketu in disguise, and the isolation has been engineered so that royal power, loyal counsel and public identity can no longer protect the king.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-hunt-separates-the-king', 'hi', 'एक सूअर राजा को सभी सुरक्षा-घेरों से दूर ले जाता है', 'शिकार के समय एक असाधारण सूअर प्रतापभानु को कठिन वन में बहुत दूर खींच ले जाता है और बार-बार उनके बाणों से बचता है। राजा सेना से बिछुड़कर थक और प्यास से व्याकुल हो जाते हैं। वह सूअर वास्तव में कालकेतु है; यह अलगाव इसलिए रचा गया है कि राजशक्ति, सच्ची सलाह और पहचान अब राजा की रक्षा न कर सकें।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-defeated-king-poses-as-a-sage', 'en', 'An old enemy receives Pratapbhanu as a holy man', 'Pratapbhanu finds an apparent hermitage. Its resident is a king whom he once defeated, now living in disguise and nursing humiliation. The enemy recognizes Pratapbhanu, but the thirsty king sees only a compassionate ascetic who shows him water and shelter. Their unequal knowledge gives the disguised king control of the encounter.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-defeated-king-poses-as-a-sage', 'hi', 'पुराना शत्रु साधु बनकर प्रतापभानु को आश्रय देता है', 'प्रतापभानु को एक आश्रम दिखाई देता है। वहाँ वही राजा साधु-वेश में रहता है जिसे उन्होंने कभी हराया था और जो अपमान भीतर दबाए हुए है। शत्रु प्रतापभानु को पहचान लेता है, पर प्यासे राजा को केवल जल और आश्रय देने वाला दयालु तपस्वी दिखाई देता है। पहचान की यह असमानता कपटी राजा को पूरी स्थिति पर नियंत्रण दे देती है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ekatanu-wins-the-kings-confidence', 'en', 'The false sage turns flattery into trust', 'Calling himself Bhikhari and then Ekatanu, the disguised enemy claims an ancient life and hidden spiritual power. He reveals Pratapbhanu''s name and family without being told, which convinces the king that he possesses supernatural knowledge. He then offers long life and unconquered rule, while quietly identifying a brahmin curse as the one danger the king must fear.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ekatanu-wins-the-kings-confidence', 'hi', 'कपटी मुनि प्रशंसा को विश्वास में बदलता है', 'कपटी शत्रु पहले अपना नाम भिखारी और फिर एकतनु बताकर प्राचीन आयु तथा गुप्त सिद्धि का दावा करता है। बिना बताए प्रतापभानु का नाम और वंश कह देने से राजा को उसके अलौकिक ज्ञान पर विश्वास हो जाता है। वह दीर्घ आयु और अजेय राज्य का लोभ देता है, साथ ही चुपचाप यह भय बैठाता है कि केवल ब्राह्मणों का श्राप राजा का अंत कर सकता है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'a-year-of-feasts-becomes-the-trap', 'en', 'The promised solution places the kingdom inside the enemy''s plan', 'The false sage tells Pratapbhanu that if he personally feeds vast numbers of brahmins and their families for a year, they will come under his influence and no curse will threaten him. He promises to appear secretly as the royal priest and prepare the meals. A plan that looks like generosity is therefore tied to the king''s desire for permanent control and fearlessness.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'a-year-of-feasts-becomes-the-trap', 'hi', 'बताया गया उपाय राज्य को शत्रु की योजना में फँसा देता है', 'कपटी मुनि कहता है कि यदि प्रतापभानु एक वर्ष तक बड़ी संख्या में ब्राह्मणों और उनके परिवारों को स्वयं भोजन कराएँ तो वे राजा के प्रभाव में आ जाएँगे और श्राप का भय मिट जाएगा। वह राजपुरोहित का रूप लेकर गुप्त रूप से भोजन बनाने का वचन देता है। बाहर से दान दिखने वाली योजना इस तरह राजा की स्थायी नियंत्रण और निर्भयता की इच्छा से बँध जाती है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'kalaketu-completes-the-deception', 'en', 'Kalaketu carries the plot from forest to palace', 'Kalaketu—the demon who took the boar''s form and has his own losses to avenge—joins the defeated king. He returns the sleeping Pratapbhanu and horse to the palace, removes the real priest and assumes his appearance. In the royal kitchen the conspirators contaminate the feast with meat identified in the story as including a brahmin''s flesh.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'kalaketu-completes-the-deception', 'hi', 'कालकेतु वन की साजिश को राजमहल तक पहुँचाता है', 'सूअर का रूप लेने वाला कालकेतु, जिसके अपने प्रतिशोध हैं, पराजित राजा से मिल जाता है। वह सोए हुए प्रतापभानु और घोड़े को महल पहुँचा देता है, असली पुरोहित को हटाकर उसका रूप धारण करता है। राजरसोई में षड्यंत्रकारी भोजन को ऐसे मांस से अपवित्र करते हैं जिसे कथा ब्राह्मण-मांस भी बताती है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-feast-is-stopped-and-the-curse-falls', 'en', 'A warning prevents the meal but not the curse', 'As the invited guests are about to eat, a heavenly warning declares the food unfit. Believing Pratapbhanu planned the outrage, the assembled brahmins curse him and his household to become demons and perish. A second voice states that the king did not knowingly commit the crime, but the curse, once spoken, is not withdrawn.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-feast-is-stopped-and-the-curse-falls', 'hi', 'आकाशवाणी भोजन रोक देती है, पर श्राप नहीं रुकता', 'अतिथि भोजन करने ही वाले होते हैं कि आकाशवाणी उसे अपवित्र बताकर रोक देती है। यह मानकर कि प्रतापभानु ने जानबूझकर अपमान रचा है, ब्राह्मण उन्हें और उनके कुल को राक्षस होने तथा नष्ट होने का श्राप देते हैं। दूसरी आकाशवाणी कहती है कि राजा ने जानकर अपराध नहीं किया, फिर भी बोला हुआ श्राप वापस नहीं लिया जाता।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'enemy-kings-destroy-pratapbhanus-house', 'en', 'The curse works through political enemies and war', 'The disguised enemies spread news that breaks confidence in Pratapbhanu. Formerly defeated kings unite, surround his city and wage war. Pratapbhanu and Arimardana fall, and Satyaketu''s line is destroyed. The sacred narrative combines curse and human political consequence rather than depicting the kingdom as vanishing without action.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'enemy-kings-destroy-pratapbhanus-house', 'hi', 'श्राप राजनीतिक शत्रुओं और युद्ध के माध्यम से पूरा होता है', 'कपटी शत्रु ऐसी खबर फैलाते हैं जिससे प्रतापभानु पर विश्वास टूटता है। पहले पराजित राजा एकजुट होकर नगर घेरते हैं और युद्ध करते हैं। प्रतापभानु तथा अरिमर्दन मारे जाते हैं और सत्यकेतु का वंश समाप्त हो जाता है। पवित्र कथा श्राप को मानवीय राजनीतिक परिणाम के साथ जोड़ती है; राज्य बिना घटनाक्रम के अचानक गायब नहीं होता।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-household-is-reborn-in-lanka', 'en', 'Pratapbhanu''s household returns as Ravana''s household', 'Within this Ramcharitmanas account, Pratapbhanu is reborn as Ravana, Arimardana as Kumbhakarna and the minister Dharmaruchi as Vibhishana. Their people become a vast demon host. This causal mapping belongs to this expression and must remain separate from other accounts of Ravana''s ancestry and birth.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-household-is-reborn-in-lanka', 'hi', 'प्रतापभानु का परिवार रावण के परिवार के रूप में लौटता है', 'रामचरितमानस की इस कथा में प्रतापभानु रावण, अरिमर्दन कुंभकर्ण और मंत्री धर्मरुचि विभीषण के रूप में जन्म लेते हैं। उनके लोग विशाल राक्षस-समूह बनते हैं। यह कारण-मानचित्र इसी कथा-परंपरा का है; रावण के वंश और जन्म की अन्य कथाओं से इसे अलग पहचानना आवश्यक है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'three-brothers-choose-different-boons', 'en', 'Ravana, Kumbhakarna and Vibhishana reveal different aims', 'The brothers undertake immense austerities and receive boons. Ravana seeks protection from almost every powerful class while dismissing humans and monkeys; Kumbhakarna''s boon becomes prolonged sleep; Vibhishana asks for unwavering devotion to the divine. Their shared origin does not erase their different choices.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'three-brothers-choose-different-boons', 'hi', 'रावण, कुंभकर्ण और विभीषण अलग-अलग इच्छाएँ प्रकट करते हैं', 'तीनों भाई कठोर तप करते हैं और वर पाते हैं। रावण लगभग सभी शक्तिशाली जातियों से सुरक्षा माँगते हुए मनुष्य और वानर को तुच्छ समझकर छोड़ देता है; कुंभकर्ण का वर लंबी निद्रा बन जाता है; विभीषण अटल भगवद्भक्ति माँगते हैं। एक जन्म-संबंध उनके अलग चुनावों को मिटाता नहीं।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ravana-builds-power-in-lanka', 'en', 'Lanka becomes the centre of Ravana''s expanding rule', 'Ravana gains Lanka, gathers family, allies, wealth and armies, and grows more confident with every success. Kumbhakarna embodies enormous force, while Vibhishana retains a devotional orientation within the same household. The kingdom''s splendour therefore grows beside an unresolved moral division.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ravana-builds-power-in-lanka', 'hi', 'लंका रावण के फैलते शासन का केंद्र बनती है', 'रावण लंका प्राप्त करता है और परिवार, सहयोगी, संपत्ति तथा सेनाएँ जुटाता जाता है। हर सफलता के साथ उसका आत्मविश्वास और अहंकार बढ़ते हैं। कुंभकर्ण असाधारण बल का रूप है, जबकि विभीषण उसी परिवार के भीतर भक्ति की दिशा बनाए रखते हैं; वैभव के साथ नैतिक विभाजन भी बढ़ता है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ravanas-rule-becomes-oppression', 'en', 'Conquest turns into a world where dissent and worship are attacked', 'Ravana challenges the guardians of the directions, subdues peoples and orders disruption of sacrifices, recitation and independent religious life. Fear spreads so widely that the earth is personified as unable to bear the weight of hostility toward others. The story''s problem is no longer one king''s curse; it is the world produced by unchecked power.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ravanas-rule-becomes-oppression', 'hi', 'विजय ऐसा शासन बन जाती है जहाँ विरोध और साधना दोनों दबते हैं', 'रावण दिक्पालों को चुनौती देता है, लोगों को अधीन करता है और यज्ञ, पाठ तथा स्वतंत्र धार्मिक जीवन में बाधा डालने का आदेश देता है। भय इतना फैलता है कि पृथ्वी को परद्रोह का भार न सह पाने वाली गाय के रूप में दिखाया जाता है। अब समस्या केवल एक राजा का श्राप नहीं, निरंकुश शक्ति से बना पूरा संसार है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-world-asks-for-relief', 'en', 'Earth, sages and gods seek an answer together', 'Earth takes the form of a cow and brings her suffering before sages and gods. They turn to Brahma, but the search for a distant divine location is corrected by Shiva''s insight that the divine is present everywhere and manifests through love. Their appeal receives the assurance that help will come in human form.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-world-asks-for-relief', 'hi', 'पृथ्वी, ऋषि और देवता मिलकर समाधान खोजते हैं', 'पृथ्वी गाय का रूप लेकर अपना दुख ऋषियों और देवताओं के सामने रखती है। वे ब्रह्मा के पास जाते हैं, पर ईश्वर को किसी दूर स्थान में खोजने की प्रवृत्ति को शिव की यह बात सुधारती है कि प्रभु सर्वत्र हैं और प्रेम से प्रकट होते हैं। सामूहिक प्रार्थना के उत्तर में मनुष्य रूप में सहायता आने का आश्वासन मिलता है।'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-incarnation-promise-closes-the-antecedent', 'en', 'The promise of four brothers carries the story toward Ayodhya', 'The divine assurance joins the earlier antecedents: a birth in the solar dynasty, four brothers, the presence of the primordial power and the fulfilment of Narada''s words. The gods are instructed to take monkey forms and prepare to assist. With the opposing forces now in place, the telling returns to King Dasharatha and the awaited births in Ayodhya.'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'the-incarnation-promise-closes-the-antecedent', 'hi', 'चार भाइयों का वचन कथा को अयोध्या की ओर ले जाता है', 'दिव्य आश्वासन पहले कही कारण-कथाओं को जोड़ता है—सूर्यवंश में जन्म, चार भाई, आदिशक्ति की उपस्थिति और नारद के शब्दों की पूर्ति। देवताओं को वानर रूप लेकर सहायता के लिए तैयार होने को कहा जाता है। दोनों पक्षों की भूमिका बन जाने पर कथा राजा दशरथ और अयोध्या में प्रतीक्षित जन्मों की ओर लौटती है।'),
  ('ramayana-manas-rama-childhood-education-v1', 'kausalya-asks-for-the-child-she-can-love', 'en', 'The divine infant becomes Kausalya''s child', 'At Rama''s birth, Kausalya beholds a divine form rather than only an ordinary infant. She praises what she sees but asks that the overwhelming manifestation give way to a child she can hold and love. Rama accepts that maternal relationship and begins to cry and behave as a baby, allowing devotion to become everyday care.'),
  ('ramayana-manas-rama-childhood-education-v1', 'kausalya-asks-for-the-child-she-can-love', 'hi', 'दिव्य शिशु कौसल्या का बालक बनता है', 'राम के जन्म पर कौसल्या केवल सामान्य शिशु नहीं, दिव्य रूप देखती हैं। वे उस स्वरूप की स्तुति करती हैं, फिर चाहती हैं कि विराट दर्शन ऐसे बालक में बदल जाए जिसे वे गोद में लेकर प्रेम कर सकें। राम मातृ-संबंध स्वीकार करते हैं और शिशु की तरह रोने-खेलने लगते हैं; भक्ति अब रोजमर्रा की देखभाल बन जाती है।'),
  ('ramayana-manas-rama-childhood-education-v1', 'the-four-brothers-fill-the-palace-with-play', 'en', 'Four brothers grow inside a household of affection', 'Rama, Bharata, Lakshmana and Shatrughna pass infancy together while the queens and Dasharatha delight in their changing expressions, movement and play. The narration does not isolate Rama from his brothers; paired affection and shared childhood establish relationships that later survive separation, exile and rule.'),
  ('ramayana-manas-rama-childhood-education-v1', 'the-four-brothers-fill-the-palace-with-play', 'hi', 'चारों भाई स्नेह से भरे घर में बड़े होते हैं', 'राम, भरत, लक्ष्मण और शत्रुघ्न साथ-साथ शैशव बिताते हैं। रानियाँ और दशरथ उनके बदलते हावभाव, चलने और खेल में आनंद पाते हैं। कथा राम को भाइयों से अलग नहीं करती; साथ का बाल्यकाल और जोड़ीदार स्नेह आगे वनवास, दूरी और राजकाज में भी संबंधों की नींव बना रहता है।'),
  ('ramayana-manas-rama-childhood-education-v1', 'kausalya-sees-the-universe-within-rama', 'en', 'A domestic moment opens into a cosmic vision', 'Kausalya places the child down, prepares worship and then seems to see Rama both eating the offered food and lying where she left him. Her confusion gives way to a vision of countless worlds within him. When the vision becomes too much, she asks to return to the ordinary mother-child relationship, and the mystery is kept within the household.'),
  ('ramayana-manas-rama-childhood-education-v1', 'kausalya-sees-the-universe-within-rama', 'hi', 'घर का एक क्षण विराट दर्शन में खुल जाता है', 'कौसल्या बालक को सुलाकर पूजा की तैयारी करती हैं, फिर उन्हें राम भोग ग्रहण करते हुए भी और वहीं लेटे हुए भी दिखाई देते हैं। आश्चर्य के बीच उन्हें राम के भीतर असंख्य ब्रह्मांडों का दर्शन होता है। जब वह अनुभव असह्य होने लगता है, वे फिर सामान्य माँ-बेटे का संबंध चाहती हैं और यह रहस्य घर के भीतर ही रहता है।'),
  ('ramayana-manas-rama-childhood-education-v1', 'rama-runs-through-ayodhyas-courtyards', 'en', 'The child who contains worlds runs from his mother', 'Rama crawls, totters and joins groups of children in play. When Kausalya calls him, he sometimes runs away laughing until she catches him. The contrast is central to the scene: the one whom sages cannot fully comprehend is available to a mother''s pursuit, touch and affection.'),
  ('ramayana-manas-rama-childhood-education-v1', 'rama-runs-through-ayodhyas-courtyards', 'hi', 'ब्रह्मांड समेटे बालक माँ से खेलते हुए दूर भागता है', 'राम घुटनों चलते हैं, ठुमकते हैं और बालकों की टोली में खेलते हैं। कौसल्या बुलाती हैं तो कभी वे हँसते हुए दूर भागते हैं, फिर माँ उन्हें पकड़ लेती हैं। प्रसंग का आनंद इसी विरोध में है—जिन्हें मुनि पूरी तरह नहीं जान पाते, वे माँ की पुकार, पकड़ और स्नेह में सहज उपलब्ध हैं।'),
  ('ramayana-manas-rama-childhood-education-v1', 'the-brothers-enter-formal-learning', 'en', 'Ceremonies lead the brothers into study', 'The family completes the appropriate childhood ceremonies and the brothers go to their guru for education. Rama is said to master learning quickly, but the scene still places knowledge inside a teacher-student relationship and alongside all four brothers. Divine identity does not erase participation in human learning.'),
  ('ramayana-manas-rama-childhood-education-v1', 'the-brothers-enter-formal-learning', 'hi', 'संस्कारों के बाद चारों भाई अध्ययन में प्रवेश करते हैं', 'परिवार बाल्यकाल के आवश्यक संस्कार पूरे करता है और चारों भाई शिक्षा के लिए गुरु के पास जाते हैं। राम अल्प समय में विद्या ग्रहण करते हैं, फिर भी कथा ज्ञान को गुरु-शिष्य संबंध और चारों भाइयों के साझा अध्ययन के भीतर रखती है। दिव्य पहचान मानवीय सीखने की प्रक्रिया को समाप्त नहीं करती।'),
  ('ramayana-manas-rama-childhood-education-v1', 'learning-continues-through-games-and-public-life', 'en', 'Games rehearse movement, cooperation and responsibility', 'The growing princes play with companions, practise the skills associated with royal life and move through Ayodhya in ways that let its people know them. The text compresses this period, but it marks the bridge from protected childhood to public action. They are no longer only children inside the palace.'),
  ('ramayana-manas-rama-childhood-education-v1', 'learning-continues-through-games-and-public-life', 'hi', 'खेलों में गति, सहयोग और जिम्मेदारी का अभ्यास होता है', 'बड़े होते राजकुमार साथियों के साथ खेलते हैं, राजकुमारों से जुड़े कौशलों का अभ्यास करते हैं और अयोध्या में लोगों के बीच जाते हैं। पाठ इस काल को संक्षेप में कहता है, फिर भी यह सुरक्षित बाल्यकाल से सार्वजनिक कर्म की ओर स्पष्ट पुल है। वे अब केवल महल के भीतर के बालक नहीं रहे।'),
  ('ramayana-manas-rama-childhood-education-v1', 'vishvamitras-arrival-ends-childhood', 'en', 'The next visitor will ask that training be used', 'The childhood sequence closes with the princes educated, bonded and ready to act. Vishvamitra''s arrival will ask Dasharatha to let Rama and Lakshmana leave the palace to protect a sacrifice. That request begins their first journey beyond Ayodhya and carries the story toward Mithila.'),
  ('ramayana-manas-rama-childhood-education-v1', 'vishvamitras-arrival-ends-childhood', 'hi', 'अगला अतिथि शिक्षा को वास्तविक परीक्षा में लगाने वाला है', 'बाल्यकाल का क्रम चारों भाइयों को शिक्षित, परस्पर जुड़े और कर्म के लिए तैयार छोड़ता है। विश्वामित्र का आगमन दशरथ से राम और लक्ष्मण को यज्ञ-रक्षा के लिए महल से बाहर भेजने की माँग करेगा। यही अनुरोध उनकी अयोध्या से बाहर पहली यात्रा और मिथिला की दिशा शुरू करता है।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'the-brothers-enter-janakas-garden', 'en', 'A simple request for flowers opens the meeting', 'In Mithila, Vishvamitra sends Rama and Lakshmana to gather flowers for worship. They enter Janaka''s carefully tended garden, moving among flowering trees, birds and a pond. The scene begins as service to their teacher, not as a planned meeting with Sita.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'the-brothers-enter-janakas-garden', 'hi', 'फूल लाने का साधारण कार्य पहली भेंट का मार्ग खोलता है', 'मिथिला में विश्वामित्र राम और लक्ष्मण को पूजा के लिए फूल लाने भेजते हैं। दोनों जनक की सँवरी हुई वाटिका में फूलों, पक्षियों और सरोवर के बीच पहुँचते हैं। प्रसंग गुरु की सेवा से शुरू होता है, सीता से मिलने की पूर्व-योजना से नहीं।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'sita-arrives-to-worship-gauri', 'en', 'Sita comes with companions for Gauri worship', 'Sita enters the garden with her companions to worship Gauri. One companion wanders ahead, sees the two visiting princes and returns visibly moved by their appearance. Her excitement creates curiosity but does not force Sita forward; the friends together lead the encounter.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'sita-arrives-to-worship-gauri', 'hi', 'सीता सखियों के साथ गौरी-पूजन के लिए आती हैं', 'सीता सखियों के साथ गौरी-पूजन के लिए वाटिका में आती हैं। एक सखी आगे जाकर दोनों अतिथि राजकुमारों को देखती है और उनके रूप से प्रभावित होकर लौटती है। उसका उत्साह जिज्ञासा जगाता है, पर सीता को अकेले आगे नहीं धकेलता; सखियाँ मिलकर इस भेंट का मार्ग बनाती हैं।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'anklets-draw-ramas-attention', 'en', 'The sound of ornaments turns Rama toward Sita', 'As Sita and her companions approach, the sound of their ornaments reaches Rama. He tells Lakshmana that King Janaka''s daughter, for whom the bow ceremony is being held, seems to be in the garden for Gauri worship. When he sees her, observation becomes an inward recognition that he carefully contains within family honour and self-discipline.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'anklets-draw-ramas-attention', 'hi', 'आभूषणों की ध्वनि राम का ध्यान सीता की ओर ले जाती है', 'सीता और सखियाँ पास आती हैं तो उनके आभूषणों की ध्वनि राम तक पहुँचती है। राम लक्ष्मण से कहते हैं कि धनुष-समारोह से जुड़ी जनककुमारी शायद गौरी-पूजन के लिए आई हैं। सीता को देखकर साधारण जानकारी भीतर की पहचान बन जाती है, जिसे राम कुल-मर्यादा और आत्मसंयम के भीतर सँभालते हैं।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'sita-sees-rama', 'en', 'Sita''s first sight carries recognition and uncertainty', 'The companions show Sita the brothers through the garden growth. Sita looks at Rama and becomes absorbed, while a perceptive friend helps her return to the present moment. The feeling is powerful but not yet a promise: Sita remains aware of Janaka''s bow vow and of how little control she has over the coming public test.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'sita-sees-rama', 'hi', 'सीता के प्रथम दर्शन में पहचान और अनिश्चितता साथ हैं', 'सखियाँ लताओं की ओट से सीता को दोनों भाइयों का दर्शन कराती हैं। सीता राम को देखकर तन्मय हो जाती हैं और एक समझदार सखी उन्हें वर्तमान क्षण में लौटाती है। भावना गहरी है, पर अभी प्रतिज्ञा नहीं; सीता को जनक की धनुष-शर्त और आने वाली सार्वजनिक परीक्षा पर अपने सीमित अधिकार का भान है।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'both-carry-the-image-away', 'en', 'The meeting ends, but each carries the other inwardly', 'Time at the garden is running out. Sita turns back more than once under the pretext of looking at trees, birds and deer, while Rama holds her image in his mind. Their paths separate physically without conversation or secret arrangement, preserving both mutual attraction and the uncertainty of what the bow ceremony will decide.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'both-carry-the-image-away', 'hi', 'भेंट समाप्त होती है, पर दोनों एक-दूसरे की छवि साथ ले जाते हैं', 'वाटिका में समय समाप्त हो रहा है। सीता वृक्ष, पक्षी और हिरन देखने के बहाने बार-बार पीछे मुड़ती हैं, जबकि राम उनकी छवि मन में रख लेते हैं। बिना बातचीत या गुप्त योजना के दोनों के मार्ग अलग होते हैं; आकर्षण बना रहता है और धनुष-समारोह का परिणाम अभी अनिश्चित है।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'sita-returns-to-gauri', 'en', 'Sita brings the unspoken hope to Gauri', 'Sita returns to Gauri''s shrine and offers praise before expressing that the goddess already knows the desire she cannot openly state. The prayer joins personal feeling with the goddess''s own story of steadfast love and marriage to Shiva. Sita seeks blessing rather than attempting to bypass the public condition set by her father.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'sita-returns-to-gauri', 'hi', 'सीता अपनी अनकही आशा गौरी के सामने रखती हैं', 'सीता गौरी के मंदिर लौटकर स्तुति करती हैं और कहती हैं कि देवी उस इच्छा को जानती हैं जिसे वे खुलकर नहीं कह पा रही हैं। प्रार्थना उनके निजी भाव को गौरी के अपने तप, प्रेम और शिव-विवाह की कथा से जोड़ती है। सीता पिता की सार्वजनिक शर्त को छलकर हटाने के बजाय आशीर्वाद माँगती हैं।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'gauri-gives-her-blessing', 'en', 'The shrine answers with reassurance', 'Within the sacred telling, Gauri''s image responds, a garland falls and the goddess blesses Sita. The reassurance is specific: the dark-hued person already held in Sita''s heart will become her husband and understands her character and affection. Sita leaves joyful, but the human sequence of the bow and Janaka''s vow still has to unfold.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'gauri-gives-her-blessing', 'hi', 'मंदिर से आश्वासन मिलता है', 'पवित्र कथा में गौरी की मूर्ति प्रसन्न होती है, माला गिरती है और देवी सीता को आशीर्वाद देती हैं। आश्वासन स्पष्ट है—जिस श्याम रूप को सीता ने मन में रखा है वही उनके पति होंगे और उनके शील-स्नेह को जानते हैं। सीता प्रसन्न लौटती हैं, फिर भी धनुष और जनक की प्रतिज्ञा का मानवीय क्रम अभी पूरा होना बाकी है।'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'rama-returns-to-his-teacher', 'en', 'The private recognition moves toward the public bow hall', 'Rama and Lakshmana return from the garden to Vishvamitra. The next movement places them among the assembled rulers and before Shiva''s bow. The garden has supplied emotional knowledge; the bow hall will test action, authority and the conditions under which Rama and Sita can be joined.'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'rama-returns-to-his-teacher', 'hi', 'निजी पहचान अब सार्वजनिक धनुष-सभा की ओर बढ़ती है', 'राम और लक्ष्मण वाटिका से विश्वामित्र के पास लौटते हैं। अगला चरण उन्हें एकत्र राजाओं और शिवधनुष के सामने ले जाएगा। वाटिका ने भावनात्मक पहचान दी है; धनुष-सभा कर्म, अधिकार और राम-सीता के मिलन की सार्वजनिक शर्तों की परीक्षा करेगी।'),
  ('ramayana-manas-kevat-crossing-v1', 'the-exiles-need-a-boat', 'en', 'The road out of Ayodhya reaches the Ganga', 'Rama, Sita and Lakshmana have left royal transport behind and must cross the Ganga to continue into exile. Guha''s people call for a boat, but Kevat does not immediately bring it forward. The delay places a working boatman, rather than a king or sage, in control of the next necessary movement.'),
  ('ramayana-manas-kevat-crossing-v1', 'the-exiles-need-a-boat', 'hi', 'अयोध्या से निकला मार्ग गंगा तट पर पहुँचता है', 'राम, सीता और लक्ष्मण राजसी वाहन छोड़ चुके हैं और वनवास की यात्रा आगे बढ़ाने के लिए गंगा पार करनी है। गुह के लोग नाव बुलाते हैं, पर केवट उसे तुरंत आगे नहीं लाते। इस ठहराव में अगले अनिवार्य कदम का अधिकार किसी राजा या ऋषि के नहीं, एक श्रमजीवी नाविक के हाथ में आता है।'),
  ('ramayana-manas-kevat-crossing-v1', 'kevat-names-his-condition', 'en', 'Kevat turns the Ahalya story into a playful precaution', 'Kevat says he knows the transforming power attributed to the dust of Rama''s feet: a stone became a woman in Ahalya''s story. His boat is wooden and supports his family, so he jokes that he cannot risk it changing as well. Beneath the humour is his real condition—he wants to wash Rama''s feet before allowing anyone aboard.'),
  ('ramayana-manas-kevat-crossing-v1', 'kevat-names-his-condition', 'hi', 'केवट अहल्या की कथा को हँसते हुए सावधानी का कारण बनाते हैं', 'केवट कहते हैं कि वे राम के चरणों की धूल की परिवर्तनकारी शक्ति जानते हैं—अहल्या की कथा में पत्थर स्त्री बन गया था। उनकी नाव लकड़ी की है और उसी से परिवार चलता है, इसलिए वे हँसते हुए कहते हैं कि नाव बदल जाने का जोखिम नहीं ले सकते। विनोद के भीतर उनकी असली शर्त है—नाव पर चढ़ाने से पहले वे राम के चरण धोना चाहते हैं।'),
  ('ramayana-manas-kevat-crossing-v1', 'rama-accepts-kevats-request', 'en', 'Rama answers insistence with consent and humour', 'Kevat insists that he wants no fare for the washing and is prepared to wait rather than move the boat without it. Rama looks toward Sita and Lakshmana and smiles at the devotion wrapped in awkward, playful speech. He permits Kevat to bring water and complete the service he has chosen.'),
  ('ramayana-manas-kevat-crossing-v1', 'rama-accepts-kevats-request', 'hi', 'राम केवट के आग्रह को सहमति और मुस्कान से स्वीकार करते हैं', 'केवट कहते हैं कि चरण धोने के बदले उन्हें कोई उतराई नहीं चाहिए और बिना यह सेवा किए वे नाव नहीं चलाएँगे। अटपटी, विनोदी वाणी में लिपटी भक्ति देखकर राम सीता और लक्ष्मण की ओर देखते हुए मुस्कराते हैं। वे केवट को जल लाकर अपनी चुनी सेवा पूरी करने की अनुमति देते हैं।'),
  ('ramayana-manas-kevat-crossing-v1', 'kevat-washes-ramas-feet', 'en', 'The boatman''s household shares the moment', 'Kevat brings water, washes Rama''s feet with intense joy and shares the sanctified water with his household as the devotional telling describes. The scene reverses ordinary status: the traveller who needs transport accepts service from the boatman, while the boatman understands the meeting as wealth greater than a fare.'),
  ('ramayana-manas-kevat-crossing-v1', 'kevat-washes-ramas-feet', 'hi', 'नाविक का परिवार भी इस सेवा में सहभागी होता है', 'केवट जल लाते हैं, अत्यंत आनंद से राम के चरण धोते हैं और भक्तिकथा के अनुसार उस चरणोदक को परिवार के साथ ग्रहण करते हैं। सामान्य पद-क्रम उलट जाता है—जिस यात्री को नाव चाहिए वह नाविक की सेवा स्वीकार करता है, और नाविक इस मिलन को किसी उतराई से बड़ी संपदा मानता है।'),
  ('ramayana-manas-kevat-crossing-v1', 'the-boat-crosses-the-ganga', 'en', 'Kevat carries the travellers to the far bank', 'With the condition fulfilled, Rama, Sita, Lakshmana and Guha enter the boat and Kevat takes them across. The physical crossing moves the exiles farther from Ayodhya and deeper into an uncertain life. The narration also plays on another crossing: Rama is remembered as one who carries devotees across the ocean of existence, yet here asks a boatman for help.'),
  ('ramayana-manas-kevat-crossing-v1', 'the-boat-crosses-the-ganga', 'hi', 'केवट यात्रियों को गंगा के दूसरे तट तक ले जाते हैं', 'शर्त पूरी होने पर राम, सीता, लक्ष्मण और गुह नाव में बैठते हैं और केवट उन्हें पार ले जाते हैं। यह भौतिक पारगमन वनवासियों को अयोध्या से और दूर तथा अनिश्चित जीवन में और भीतर पहुँचाता है। कथा एक दूसरी उपमा भी रखती है—जो राम भक्तों को भवसागर पार कराते हैं, वे यहाँ नाविक से सहायता माँग रहे हैं।'),
  ('ramayana-manas-kevat-crossing-v1', 'sita-offers-the-ring-as-fare', 'en', 'Sita understands Rama''s concern about payment', 'On the far bank, Rama feels the discomfort of having received labour without payment. Sita reads his concern and removes a jeweled ring so that he can offer it as fare. Her action makes the economic reality visible even inside a devotional scene: a boatman''s work ordinarily deserves payment.'),
  ('ramayana-manas-kevat-crossing-v1', 'sita-offers-the-ring-as-fare', 'hi', 'सीता उतराई को लेकर राम का संकोच समझती हैं', 'दूसरे तट पर राम को बिना भुगतान श्रम लेने का संकोच होता है। सीता उनकी चिंता समझकर मणि-जड़ी अंगूठी उतारती हैं ताकि उसे उतराई के रूप में दिया जा सके। भक्तिकथा के भीतर भी उनका यह कदम आर्थिक वास्तविकता दिखाता है—नाविक के श्रम का सामान्यतः मूल्य होता है।'),
  ('ramayana-manas-kevat-crossing-v1', 'kevat-refuses-payment', 'en', 'Kevat defines what he has already received', 'Kevat refuses the ring by his own choice. He says the meeting has ended the poverty and sorrow that mattered to him and that he needs nothing more now; if Rama gives something on the return journey, he will receive it as grace. The refusal is personal devotion, not a rule that workers should waive payment.'),
  ('ramayana-manas-kevat-crossing-v1', 'kevat-refuses-payment', 'hi', 'केवट बताते हैं कि उन्हें क्या मिल चुका है', 'केवट अपनी इच्छा से अंगूठी लेने से मना करते हैं। वे कहते हैं कि इस मिलन ने उनके लिए महत्वपूर्ण दरिद्रता और दुख मिटा दिए हैं और अभी उन्हें कुछ नहीं चाहिए; लौटते समय राम कुछ देंगे तो उसे प्रसाद मानेंगे। यह उनका निजी भक्तिभाव है, श्रमिकों से भुगतान छोड़ने की सामान्य अपेक्षा नहीं।'),
  ('ramayana-manas-kevat-crossing-v1', 'rama-blesses-kevat-and-the-road-continues', 'en', 'The exchange ends with blessing, not a commercial debt', 'Rama, Sita and Lakshmana continue to urge Kevat, but he accepts no material fare. Rama gives him the blessing of pure devotion and the companions part. Sita then turns to the Ganga with a prayer for their safe return, carrying the story from this completed crossing into the longer uncertainty of exile.'),
  ('ramayana-manas-kevat-crossing-v1', 'rama-blesses-kevat-and-the-road-continues', 'hi', 'लेन-देन वाणिज्यिक ऋण नहीं, आशीर्वाद के साथ समाप्त होता है', 'राम, सीता और लक्ष्मण फिर आग्रह करते हैं, पर केवट भौतिक उतराई नहीं लेते। राम उन्हें निर्मल भक्ति का वर देते हैं और सब विदा होते हैं। इसके बाद सीता गंगा से सुरक्षित लौटने की प्रार्थना करती हैं; पूरा हुआ यह पारगमन कथा को वनवास की लंबी अनिश्चितता में आगे ले जाता है।')
) as source(moment_slug, beat_slug, language_code, title, narration)
join public.narrative_series series on series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1'
join public.narrative_moments moment on moment.series_id=series.id and moment.slug=source.moment_slug
join public.narrative_beats beat on beat.moment_id=moment.id and beat.slug=source.beat_slug
on conflict (beat_id, language_code) do update set title=excluded.title, narration=excluded.narration, text_status=excluded.text_status,
  rights_lane=excluded.rights_lane, publication_state=excluded.publication_state, updated_at=now();

insert into public.narrative_moment_links (source_moment_id, target_moment_id, link_kind, label)
select source_moment.id, target_moment.id, source.link_kind, 'source-ordered expected-story traversal'
from (values
  ('ramayana-manas-shiva-sati-parvati-frame-v1', 'ramayana-manas-narada-delusion-v1', 'precedes'),
  ('ramayana-manas-narada-delusion-v1', 'ramayana-manas-shiva-sati-parvati-frame-v1', 'follows'),
  ('ramayana-manas-narada-delusion-v1', 'ramayana-manas-manu-shatarupa-boon-v1', 'precedes'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'ramayana-manas-narada-delusion-v1', 'follows'),
  ('ramayana-manas-manu-shatarupa-boon-v1', 'ramayana-manas-pratapbhanu-curse-v1', 'precedes'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ramayana-manas-manu-shatarupa-boon-v1', 'follows'),
  ('ramayana-manas-pratapbhanu-curse-v1', 'ramayana-manas-rama-childhood-education-v1', 'precedes'),
  ('ramayana-manas-rama-childhood-education-v1', 'ramayana-manas-pratapbhanu-curse-v1', 'follows'),
  ('ramayana-manas-rama-childhood-education-v1', 'ramayana-manas-pushpavatika-gauri-v1', 'precedes'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'ramayana-manas-rama-childhood-education-v1', 'follows'),
  ('ramayana-manas-pushpavatika-gauri-v1', 'ramayana-manas-kevat-crossing-v1', 'precedes'),
  ('ramayana-manas-kevat-crossing-v1', 'ramayana-manas-pushpavatika-gauri-v1', 'follows')
) as source(source_slug, target_slug, link_kind)
join public.narrative_series series on series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1'
join public.narrative_moments source_moment on source_moment.series_id=series.id and source_moment.slug=source.source_slug
join public.narrative_moments target_moment on target_moment.series_id=series.id and target_moment.slug=source.target_slug
on conflict (source_moment_id, target_moment_id, link_kind) do update set label=excluded.label;

insert into public.narrative_evidence (moment_id, passage_id, evidence_role, note)
select moment.id, passage.id, 'source_span', 'Pinned Ramcharitmanas page within the exact story scan range'
from public.narrative_series series
join public.narrative_moments moment on moment.series_id=series.id
join public.passages passage on passage.locator->>'scan_sha256'=moment.source_range->>'scanSha256'
  and (passage.locator->>'scan_page')::integer between (moment.source_range->'scanPagesInclusive'->>0)::integer
  and (moment.source_range->'scanPagesInclusive'->>1)::integer
where series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1'
on conflict (moment_id, beat_id, passage_id, evidence_role) do update set note=excluded.note;

do $devam$
declare story_count integer; beat_count integer; bilingual_story_text_count integer; bilingual_beat_text_count integer;
begin
  select count(*) into story_count from public.narrative_moments moment join public.narrative_series series on series.id=moment.series_id
  where series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1' and moment.source_range->>'snapshotContract'='DEVAM_RAMAYANA_EXPECTED_STORIES_BEGINNINGS_EXILE_DB_V1';
  select count(*) into beat_count from public.narrative_beats beat join public.narrative_moments moment on moment.id=beat.moment_id
  join public.narrative_series series on series.id=moment.series_id where series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1';
  select count(*) into bilingual_story_text_count from public.narrative_moment_texts text join public.narrative_moments moment on moment.id=text.moment_id
  join public.narrative_series series on series.id=moment.series_id where series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1';
  select count(*) into bilingual_beat_text_count from public.narrative_beat_texts text join public.narrative_beats beat on beat.id=text.beat_id
  join public.narrative_moments moment on moment.id=beat.moment_id join public.narrative_series series on series.id=moment.series_id
  where series.slug='ramcharitmanas-expected-stories-beginnings-exile-v1';
  if story_count <> 7 then raise exception 'Expected 7 Ramcharitmanas expected stories, got %', story_count; end if;
  if beat_count <> 69 then raise exception 'Expected 69 Ramcharitmanas expected-story beats, got %', beat_count; end if;
  if bilingual_story_text_count <> 14 then raise exception 'Expected 14 bilingual story texts, got %', bilingual_story_text_count; end if;
  if bilingual_beat_text_count <> 138 then raise exception 'Expected 138 bilingual beat texts, got %', bilingual_beat_text_count; end if;
end
$devam$;

commit;
